for t in range(int(input())):
	(a, b) = (input(), input())
	if int(b, 2) == 0:
		print(0)
		continue
	l = max(len(a), len(b)) + 1
	(a, b) = (a.rjust(l, '0'), b.rjust(l, '0'))
	(p, ans, c) = ('0', 0, 0)
	for i in range(1, l + 1):
		if p == '1':
			c += 1
			ans = max(ans, c)
			if a[-i] == b[-i]:
				c = 0
		else:
			c = 0
		p = '1' if (a[-i] + b[-i] + p).count('1') > 1 else '0'
	print(ans + 1)
